const lessons3=[
 {type:'grow',n:2,g:3,title:'상자 하나를 더 놓아요'},
 {type:'path',n:2,from:1,to:3,title:'2단 길 · 보고 더해요'},
 {type:'grow',n:5,g:3,title:'간식 봉지를 하나 더 놓아요'},
 {type:'path',n:5,from:1,to:3,title:'5단 길 · 보고 더해요'},
 {type:'path',n:2,from:4,to:6,title:'2단 길 · 먼저 예상해요'},
 {type:'subtract',n:2,g:6,title:'한 묶음을 빼면?'},
 {type:'path',n:5,from:4,to:6,title:'5단 길 · 먼저 예상해요'},
 {type:'repair',n:2,title:'틀린 구구단 길을 고쳐요'},
 {type:'path',n:2,from:7,to:9,title:'2단 길 · 앞의 답에서 찾아요'},
 {type:'life',n:5,g:3,title:'연필 통이 하나 더 생겼어요'},
 {type:'path',n:5,from:7,to:9,title:'5단 길 · 앞의 답에서 찾아요'},
 {type:'mixed',n:2,g:4,title:'배운 식 섞기'},
 {type:'mixed',n:5,g:3,title:'배운 식 섞기'},
 {type:'mixed',n:2,g:6,title:'배운 식 섞기'},
 {type:'check',n:2,g:7,title:'혼자 확인 · 2단'},
 {type:'check',n:5,g:5,title:'혼자 확인 · 5단'}
];
let s3={done:false};const d3=()=>lessons3[s3.i];
function start3(){s3={done:s3.done,i:0,solved:[],path:{2:0,5:0}};init3()}
function init3(){const d=d3();Object.assign(s3,{phase:d.type==='grow'?'add':d.type==='path'&&d.from===1?'open':'answer',g:d.from||d.g,opened:false,prediction:null,hint:0,retry:false,passed:false,explain:false,msg:'한 묶음에 몇 개씩 있는지 살펴봐요.'});render3()}
function blocks3(n,g,extra='',icon='■'){return `<div class="group-grid">${Array.from({length:g},(_,i)=>`<div class="group-box"><small>${i+1}묶음</small><div aria-label="${n}개">${Array(n).fill(`<span aria-hidden="true">${icon}</span>`).join(' ')}</div></div>`).join('')}${extra}</div>`}
function target3(){const d=d3();if(d.type==='repair')return 8;if(d.type==='subtract')return d.n*(d.g-1);if(d.type==='grow'||d.type==='life')return d.n*(d.g+1);return d.n*s3.g}
function reveal3(){s3.opened=true;if(s3.phase==='open')s3.phase='answer';if(s3.phase==='reveal'){s3.passed=true;s3.phase='answer';s3.msg=`새 묶음에 ${d3().n}개가 들어 있어요. 예상한 답과 맞는지 확인해요.`}render3()}
function grow3(){s3.phase='answer';s3.msg='새 상자는 아직 닫혀 있어요. 한 묶음에 든 개수만큼 더해 예상해요.';render3()}
function hint3(){s3.hint=Math.min(3,s3.hint+1);s3.retry=true;const d=d3(),g=s3.g;s3.msg=s3.hint===1?`바로 앞의 식을 떠올려요: ${d.n} × ${g-1} = ${d.n*(g-1)}`:s3.hint===2?`한 묶음에는 ${d.n}개예요. 앞의 답에 ${d.n}을 더하면 돼요.`:`그림을 세어 봐요. ${d.n*(g-1)} + ${d.n} = ${d.n*g}`;render3()}
function answer3(value){const d=d3();if(s3.passed)return;const correct=s3.explain?d.n:target3();if(value!==correct){s3.retry=true;s3.msg=s3.explain?`묶음 하나 안에 ${d.n}개씩 있어요. 묶음의 수가 1 늘면 전체 개수는 얼마나 늘까요?`:d.type==='subtract'?`한 묶음을 꺼내면 ${d.n}개가 줄어요. ${d.n*d.g}에서 ${d.n}을 빼 봐요.`:d.type==='repair'?'2 → 4 → 6 다음에도 2만큼 커져야 해요. 네 번째 수를 고쳐 봐요.':`한 묶음에는 ${d.n}개예요. 앞의 답에 ${d.n}을 더해 다시 생각해 봐요.`;render3();return}if(s3.retry){s3.retry=false;s3.hint=0;s3.opened=false;s3.msg='잘 고쳤어요! 그림 힌트를 가렸어요. 같은 질문에 한 번 더 답해 봐요.';render3();return}if(s3.explain){s3.passed=true;s3.solved.push(d.n);s3.msg=`맞아요. ${d.n}개씩 한 묶음 늘어서 답도 ${d.n} 커졌어요.`}else if(d.type==='check'){s3.explain=true;s3.msg='답을 찾았어요. 이제 왜 그런지 골라 봐요.'}else if(d.type==='grow'||d.type==='path'&&d.from===4){s3.prediction=value;s3.phase='reveal';s3.msg=`${value}개로 예상했어요. 새 묶음을 열어 확인해 봐요.`}else{s3.passed=true;s3.msg=d.type==='subtract'?`맞아요! ${d.n*d.g} − ${d.n} = ${value}. 한 묶음 줄어서 ${d.n} 작아졌어요.`:d.type==='repair'?'2 → 4 → 6 → 8 → 10. 한 칸마다 2씩 커져요.':`맞아요! 한 묶음에 ${d.n}개씩 있으니 답도 ${d.n}씩 커져요.`}render3()}
function next3(){const d=d3();if(!s3.passed)return;if(d.type==='path'){s3.path[d.n]=s3.g;if(s3.g<d.to){s3.g++;s3.opened=false;s3.prediction=null;s3.passed=false;s3.phase=d.from===1?'open':'answer';s3.hint=0;s3.msg='바로 앞에서 찾은 답을 이용해요.';render3();return}}s3.i++;if(s3.i===lessons3.length){finish3();return}init3();document.querySelector('#app').scrollIntoView?.({block:'start'})}
function render3(){view='stage3';const d=d3(),n=d.n,g=s3.g,t=d.type;let body='',question='모두 몇 개일까요?';if(t==='path'){body=`<div class="number-road" aria-label="${n}단 길">${Array.from({length:9},(_,i)=>`<div class="road-stop ${i+1===g?'current':''} ${i+1<g?'visited':''}"><small>${n} × ${i+1}</small><b>${i+1<g?n*(i+1):i+1===g&&s3.passed?n*g:'?'}</b></div>`).join('')}</div>`;if(d.from===1){body+=blocks3(n,g-1,s3.opened?`<div class="group-box new">${Array(n).fill('■').join(' ')}<small>새 묶음</small></div>`:'<div class="group-box new">? <small>아직 닫혀 있어요</small></div>');body+=`<div class="equation">${n*(g-1)} + ${s3.opened?n:'□'} = ${s3.passed?n*g:'□'}</div>`}else{body+=`<div class="equation">${n} × ${g-1} = ${n*(g-1)}<br>↓ 한 묶음 더<br>${n} × ${g} = ${s3.passed?n*g:'□'}</div>`;if(s3.opened)body+=blocks3(n,g);else if(d.from===4)body+='<p class="small">새 상자 안은 예상한 뒤 열어 봐요.</p>'}}else if(t==='grow'){body=blocks3(n,d.g,s3.phase==='add'?'':s3.opened?`<div class="group-box new">${Array(n).fill(n===5?'🍪':'■').join(' ')}<small>새 묶음</small></div>`:'<div class="group-box new">? <small>새 묶음</small></div>',n===5?'🍪':'■');body+=`<div class="equation">${n} × ${d.g} = ${n*d.g}${s3.phase!=='add'?`<br>${n*d.g} + ${n} = ${s3.passed?target3():'□'}<br>${n} × ${d.g+1} = ${s3.passed?target3():'□'}`:''}</div>`}else if(t==='subtract'){body=blocks3(n,d.g-1,`<div class="group-box removed" aria-label="꺼낸 한 묶음">${Array(n).fill('■').join(' ')}<small>한 묶음 꺼내기</small></div>`);body+=`<div class="equation">${n} × ${d.g} = ${n*d.g}<br>${n} × ${d.g-1} = ${s3.passed?target3():'□'}</div>`;question='한 묶음을 빼면 몇 개가 남을까요?'}else if(t==='repair'){body='<div class="equation">2 → 4 → 6 → <span class="number-focus">'+(s3.passed?'8':'9')+'</span> → 10</div>';question='네 번째 수 9를 어떤 수로 고칠까요?'}else if(t==='life'){body='<p>연필이 5자루씩 든 통이 3개였는데, 같은 통이 1개 더 생겼어요.</p>'+blocks3(5,3,'<div class="group-box new">✏️ ✏️ ✏️ ✏️ ✏️<small>새 통</small></div>','✏️')+`<div class="equation">5 × 3 = 15 → 5 × 4 = ${s3.passed?'20':'□'}</div>`}else{body=`<div class="equation">${t==='check'?`${n} × ${g-1} = ${n*(g-1)}<br>↓ 한 묶음 더<br>`:''}${n} × ${g} = ${s3.passed||s3.explain?target3():'□'}</div>`}if(s3.hint>=3)body+=blocks3(n,g);if(s3.explain)question='왜 답이 그렇게 변했을까요?';const choices=s3.explain?[1,n,n+1]:[...new Set([target3()-n,target3(),target3()+1])];let controls='';if(s3.phase==='add')controls='<button class="primary" onclick="grow3()">한 묶음 더 놓기 +</button>';else if(s3.phase==='open'||s3.phase==='reveal')controls=`<button class="primary" onclick="reveal3()">${s3.phase==='open'?'상자 열어 보기':'열어서 예상 확인하기'}</button>`;else controls=`<h2>${question}</h2><div class="choices">${choices.map((v,i)=>({v,key:(i+s3.i+g)%choices.length})).sort((a,b)=>a.key-b.key).map(({v})=>`<button onclick="answer3(${v})" ${s3.passed?'disabled':''}>${s3.explain?`한 묶음 늘어서 ${v} 커져요`:v}</button>`).join('')}</div>`;app.innerHTML=`<div class="topline"><span class="pill">3단계 · 한 묶음씩 늘리기</span><span class="small">활동 ${s3.i+1} / ${lessons3.length}</span></div><section class="activity"><span class="small">${n}개씩 묶어서 생각해요</span><h1 class="instruction">${d.title}</h1><div class="workspace">${body}${controls}</div><div class="feedback ${s3.passed?'good':''}" role="status">${s3.msg}</div><div class="actions">${!s3.passed&&['mixed','check','path'].includes(t)&&s3.phase==='answer'&&!s3.explain?`<button onclick="hint3()" ${s3.hint===3?'disabled':''}>${s3.hint===0?'막혔어요 · 첫 힌트':'다음 힌트'}</button>`:'<button onclick="home()">전체 단계</button>'}<button class="primary" onclick="next3()" ${s3.passed?'':'disabled'}>${t==='path'&&g<d.to?'다음 상자로 →':'다음 활동 →'}</button></div></section><p class="footer">한 묶음이 늘면, 그 묶음 안의 개수만큼 더해요.</p>`}
function dots3(rotated){return `<div class="dot-array" style="grid-template-columns:repeat(${rotated?4:3},24px)" aria-label="${rotated?'4개씩 3줄':'3개씩 4줄'}, 모두 12개의 점">${Array(12).fill('<span></span>').join('')}</div>`}
function finish3(){s3.done=s3.solved.includes(2)&&s3.solved.includes(5);s3.rotated=false;view='stage3';app.innerHTML=`<section class="activity"><span class="pill">3단계 마무리</span><h1>${s3.done?'아는 답에서 다음 답을 찾았어요!':'한 묶음의 변화를 살펴봤어요!'}</h1><p>2단은 한 묶음마다 <b>2</b>씩, 5단은 <b>5</b>씩 커져요.<br>답을 잊으면 바로 앞의 답에서 한 묶음을 더해 보세요.</p><div class="workspace"><h2>3개씩 4묶음의 점을 돌려 볼까요?</h2><div id="dots3">${dots3(false)}</div><button onclick="rotate3()">점 배열 돌리기 ↻</button><h2>돌려도 점의 수가 달라질까요?</h2><div class="choices"><button onclick="rotationAnswer3(false)">달라져요</button><button onclick="rotationAnswer3(true)">같아요</button></div><p id="rotationFeedback3" role="status">먼저 배열을 돌리고 점을 살펴봐요.</p></div><p class="small">4단계에서는 배열을 돌려 두 식의 관계를 찾아요. 4단계에서 직접 돌려 보세요.</p><div class="actions"><button class="primary" onclick="start4()">4단계로 가기</button><button onclick="start3()">3단계 다시 하기</button><button class="primary" onclick="home()">전체 단계 보기</button></div></section>`}
function rotate3(){s3.rotated=!s3.rotated;document.querySelector('#dots3').innerHTML=dots3(s3.rotated);document.querySelector('#rotationFeedback3').textContent='점이 더 생기거나 사라졌는지 살펴봐요.'}
function rotationAnswer3(ok){document.querySelector('#rotationFeedback3').textContent=ok?'맞아요! 방향은 바뀌어도 점은 모두 12개예요.':'점을 하나씩 세어 보세요. 돌리기 전과 후에 점이 더 생겼나요?'}
